import json,pathlib,hashlib,gzip,re,html
R=pathlib.Path.cwd();B=R/'campaign-artifacts/C05-343-345';Q=B/'reconciled';S=B/'semantic-review'
def load(p):return json.loads(p.read_text())
def sha(x):return hashlib.sha256(x).hexdigest()
def pin(p):
 b=p.read_bytes();return {'bytes':len(b),'sha256':sha(b)}
def put(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
# Recompute measured counts from the complete, hash-verified original assets; do not rerun source queries.
pins=load(B/'proposal-baseline.json')['source_pins']
for name in ['master','corpus']:assert pin(pathlib.Path(pins[name]['path']))=={k:pins[name][k]for k in ['bytes','sha256']}
master=json.loads(gzip.decompress(pathlib.Path(pins['master']['path']).read_bytes()));corpus=json.loads(gzip.decompress(pathlib.Path(pins['corpus']['path']).read_bytes()))
index={}
for collection in ['unified_entries','curated_entries','glossary_entries']:
 for i,v in enumerate(master[collection]):
  for term in {v.get('wylie',''),*v.get('wylie_variants',[])}:index.setdefault(term,[]).append(f'{collection}:{i}')
lexcounts=[]
for a in ['tibetan/evidence/lexical.json','english/evidence/lexical.json','english/evidence/supplemental-lexical.json']:
 for q in load(B/a)['queries']:
  keys=index.get(q['term'],[]);assert set(keys)==set(q['master_keys']) and len(keys)==q['master_count'],q['term']
  ids=[int(k.split(':')[1])+1 for k in keys if k.startswith('unified_entries:')];assert set(ids)=={r['id']for r in q['spine_rows']} and len(ids)==q['spine_count']
  for row in q['spine_rows']:assert json.loads(row['raw'])==master['unified_entries'][row['id']-1]
  lexcounts.append({'angle':a,'term':q['term'],'master_count':len(keys),'spine_count':len(ids)})
corpuscounts=[]
for rel in ['tibetan/evidence/corpus.json','english/evidence/corpus.json']:
 for q in load(B/rel)['queries']:
  field=q.get('field') or re.search(r'instr\((wylie|english|acip),',q['sql']).group(1);term=q['parameters'][0];contains='instr(' in q['sql'];exclude='C13' in q['sql']
  ids=[i+1 for i,v in enumerate(corpus) if (not exclude or v.get('course')!='C13') and ((term in v.get(field,'')) if contains else (v.get(field)==term))]
  assert len(ids)==q['count'] and set(ids)==set(q['row_ids']),(rel,term,ids,q['row_ids'])
  corpuscounts.append({'source':rel,'field':field,'parameters':q['parameters'],'count':len(ids),'row_ids':ids,'operation':'instr'if contains else '='})
put(S/'evidence/material-counts.json',{'status':'PASS','method':'Recompute original exact/substring counts over hash-verified complete master/corpus assets; no SQL or generator reruns. All queried material objects were personally read; full assets are counted, not claimed linguistically read.','lexical_queries':lexcounts,'corpus_queries':corpuscounts,'unique_full_material_objects':119,'prior_personal_full_reuse':39,'new_personal_full_reads':80})

print(json.dumps({'status':'PASS_MATERIAL_COUNTS','lexical_queries':len(lexcounts),'corpus_queries':len(corpuscounts),'new_SQL_queries':0,'new_native_generator_resolver_runs':0}))
